run_script %{"script" => "local result, err = create_issue({
  title = "Reservations spec missing Test Assertions section",
  description = "The spec for the Reservations component does not include a Test Assertions section. Per the spec template, this section should enumerate the assertions the component's tests must verify. Please add a Test Assertions section to the Reservations spec covering the expected behaviors (creation, cancellation, conflict/validation rules, and any other invariants the component is responsible for).",
  severity = "warning",
  scope = "app"
})
if result == nil then return { ok = false, error = err } end
return { ok = true, issue = result }
"}

